// frontend/src/store/userStore.js
import { reactive } from "vue";
import axios from "axios"; // 引入 Axios

// 从 localStorage 中获取用户数据并解析
const storedUserData = localStorage.getItem("userStore");
let initialUser = {};

if (storedUserData) {
  try {
    initialUser = JSON.parse(storedUserData); // 尝试解析 JSON
  } catch (error) {
    console.error("无法解析用户数据:", error);
  }
}

const state = reactive({
  user: initialUser, // 初始化用户数据
});

// 定义 mutations
const mutations = {
  setUser(state, userData) {
    if (userData) {
      state.user = userData; // 设置用户数据
      localStorage.setItem("userStore", JSON.stringify(userData)); // 更新 localStorage
    } else {
      console.error("无效的用户数据, 无法设置用户状态");
    }
  },
  clearUser(state) {
    state.user = {}; // 清除用户数据
    localStorage.removeItem("userStore"); // 同步清除 localStorage
    localStorage.removeItem("token"); // 清除 token
  },
};

// 定义 actions
const actions = {
  async register({ commit }, registrationData) {
    const { username, password } = registrationData;
    try {
      const response = await axios.post(
        "http://www.groupbuyingsystem.site/api/auth/register",
        {
          username,
          password,
        },
      );
      commit("setUser", response.data.user); // 假设返回的数据格式包含用户信息
      console.log("注册成功：", response.data.message);
    } catch (error) {
      console.error(
        "注册失败:",
        error.response?.data?.message || error.message,
      );
      throw new Error(
        error.response ? error.response.data.message : "注册失败",
      );
    }
  },

  async userLogin({ commit }, loginData) {
    const { username, password } = loginData;
    try {
      const response = await axios.post(
        "http://localhost:5000/api/auth/login",
        {
          username,
          password,
        },
      );

      // 通过 response.data.data.user 获取用户信息和 token
      commit("setUser", response.data.data.user);
      localStorage.setItem("token", response.data.data.token);
      return response.data.data; // 返回 data 以便 handleLogin 可以使用
    } catch (error) {
      console.error(
        "登录失败:",
        error.response?.data?.message || error.message,
      );
      throw new Error(
        error.response ? error.response.data.message : "登录失败",
      );
    }
  },

  async getUserInfo({ commit }) {
    try {
      const token = localStorage.getItem("token"); // 获取存储中的 token
      if (!token) {
        throw new Error("未登录");
      }
      const response = await axios.get("http://localhost:5000/api/auth/login", {
        headers: {
          Authorization: `Bearer ${token}`, // 使用 Bearer token 进行身份验证
        },
      });
      commit("setUser", response.data.user); // 更新用户信息
    } catch (error) {
      console.error(
        "获取用户信息失败:",
        error.response?.data?.message || error.message,
      );
      throw new Error(
        error.response ? error.response.data.message : "获取用户信息失败",
      );
    }
  },

  logout({ commit }) {
    commit("clearUser"); // 清除用户数据
  },
};

// 定义 getters
const getters = {
  user(state) {
    return state.user; // 直接返回用户数据
  },
  userPhoneNumber(state) {
    return state.user.phoneNumber || null; // 获取用户电话
  },
  userId(state) {
    return state.user.id || null; // 获取用户 ID
  },
  userBalance(state) {
    return state.user.AccountBalance || null; // 获取用户余额
  },
  userNickname(state) {
    return state.user.nickname || "用户"; // 获取用户昵称
  },
  userAvatar(state) {
    return state.user.avatar || "/assets/avatar.png"; // 获取用户头像
  },
};

// 导出对象
export default {
  state,
  mutations,
  actions,
  getters,
};
